// Trees: several species with distinct silhouettes, generated by code and drawn as instances.
// Broadleaf canopies are unions of spheres (distinct bumps and dark notches), a conifer is a cone made of tiers.
// The canopy and the trunk are in the mesh at unit height 0–1; where the canopy starts on a tree is given by the instance,
// so the same shape serves a forest tree with a canopy from the ground and a park tree with a bare trunk.
// For each vertex the generator marks how much it may flutter in the wind (trunk not at all, canopy edge the most).

import { hashInts, unit } from '../gen-core/index.ts';
import { lerp } from '../base/index.ts';
import type { MeshData, Uniforms, VertexLayout } from '../base/index.ts';
import type { PlantedTree, TreeSpecies } from './planting.ts';

export const TREE_ATTRIBS = { a_pos: 0, a_normal: 1, a_shade: 2, i_base: 3, i_shape: 4, i_extra: 5 } as const;

/**
 * Floats per instance: base xyz, canopy radius | height, cos and sin of rotation, hue |
 * canopy start (share of height), flexibility in wind, phase, reserve.
 */
export const TREE_INSTANCE_FLOATS = 12;

/** Floats per vertex: position 3, normal 3, shading, kind (0 canopy, 1 trunk), flutter 0–1, phase 0–1. */
const VERTEX_FLOATS = 10;
const TRUNK_SIDES = 5;
/** How much wider the trunk is at the ground than at the top. */
const TRUNK_FLARE = 1.5;

/** Colours of one species as palette row indices (the project's palette decides which rows). */
export interface TreeMaterial {
  /** Notches and underside of the canopy. */
  deep: number;
  mid: number;
  /** Lit foliage and its second hue, between which it changes according to the group's hue. */
  leaf: number;
  leafAlt: number;
  trunk: number;
  /** Evergreen: does not shed in winter and does not change colour in autumn. */
  evergreen?: boolean;
}

/** How many different shapes each species has. Trees choose among them by their phase. */
const VARIANTS: Record<TreeSpecies, number> = { round: 2, tall: 2, conifer: 1, birch: 1, shrub: 1 };

/** Canopy shape from a union of spheres. Lengths are in units of the canopy radius. */
interface LumpStyle {
  lumps: number;
  /** Radius of the central sphere. */
  core: number;
  /** Offset of the bumps from the centre and their radius. The offset must be smaller than the radius, the canopy centre lies in every sphere. */
  offMin: number;
  offMax: number;
  rMin: number;
  rMax: number;
  /** Where the bumps shift vertically: a positive number is more toward the top. */
  yBias: number;
  /** From what height (−1 to 1) the underside of the canopy is flattened and how much of it remains. */
  flatBottom: number;
  flatSquash: number;
  /** How much the canopy narrows upward, 0–1. */
  taper: number;
  /** Trunk radius in canopy radii, 0 = no trunk. */
  trunk: number;
}

const LUMP_STYLE: Record<Exclude<TreeSpecies, 'conifer'>, LumpStyle> = {
  round: { lumps: 9, core: 0.66, offMin: 0.4, offMax: 0.56, rMin: 0.46, rMax: 0.6, yBias: 0.2, flatBottom: -0.5, flatSquash: 0.3, taper: 0, trunk: 0.075 },
  tall: { lumps: 12, core: 0.6, offMin: 0.34, offMax: 0.44, rMin: 0.42, rMax: 0.52, yBias: 0.0, flatBottom: -0.72, flatSquash: 0.45, taper: 0.3, trunk: 0.08 },
  birch: { lumps: 8, core: 0.5, offMin: 0.32, offMax: 0.42, rMin: 0.4, rMax: 0.5, yBias: -0.05, flatBottom: -0.8, flatSquash: 0.5, taper: 0.5, trunk: 0.06 },
  shrub: { lumps: 7, core: 0.62, offMin: 0.38, offMax: 0.52, rMin: 0.44, rMax: 0.58, yBias: 0.3, flatBottom: -0.1, flatSquash: 0, taper: 0, trunk: 0 },
};

/** Conifer: tiers, cone envelope and trunk. */
const CONIFER = { tiers: 4, tiersTop: 0.84, overlap: 0.07, envelopePower: 0.85, innerRadius: 0.42, wobble: 0.16, trunk: 0.07 } as const;

interface Shape {
  vertices: Float32Array;
  indices: Uint16Array;
}

function icosphere(subdivisions: number): { pos: number[]; idx: number[] } {
  const t = (1 + Math.sqrt(5)) / 2;
  let pos = [-1, t, 0, 1, t, 0, -1, -t, 0, 1, -t, 0, 0, -1, t, 0, 1, t, 0, -1, -t, 0, 1, -t, t, 0, -1, t, 0, 1, -t, 0, -1, -t, 0, 1];
  let idx = [0, 11, 5, 0, 5, 1, 0, 1, 7, 0, 7, 10, 0, 10, 11, 1, 5, 9, 5, 11, 4, 11, 10, 2, 10, 7, 6, 7, 1, 8, 3, 9, 4, 3, 4, 2, 3, 2, 6, 3, 6, 8, 3, 8, 9, 4, 9, 5, 2, 4, 11, 6, 2, 10, 8, 6, 7, 9, 8, 1];
  for (let s = 0; s < subdivisions; s++) {
    const mids = new Map<number, number>();
    const mid = (a: number, b: number): number => {
      const k = a < b ? a * 65536 + b : b * 65536 + a;
      let m = mids.get(k);
      if (m === undefined) {
        m = pos.length / 3;
        pos.push((pos[a * 3]! + pos[b * 3]!) / 2, (pos[a * 3 + 1]! + pos[b * 3 + 1]!) / 2, (pos[a * 3 + 2]! + pos[b * 3 + 2]!) / 2);
        mids.set(k, m);
      }
      return m;
    };
    const next: number[] = [];
    for (let i = 0; i < idx.length; i += 3) {
      const a = idx[i]!;
      const b = idx[i + 1]!;
      const c = idx[i + 2]!;
      const ab = mid(a, b);
      const bc = mid(b, c);
      const ca = mid(c, a);
      next.push(a, ab, ca, b, bc, ab, c, ca, bc, ab, bc, ca);
    }
    idx = next;
  }
  const out: number[] = [];
  for (let i = 0; i < pos.length; i += 3) {
    const l = Math.hypot(pos[i]!, pos[i + 1]!, pos[i + 2]!);
    out.push(pos[i]! / l, pos[i + 1]! / l, pos[i + 2]! / l);
  }
  pos = out;
  return { pos, idx };
}

function smooth01(t: number): number {
  const c = t < 0 ? 0 : t > 1 ? 1 : t;
  return c * c * (3 - 2 * c);
}

/** Adds a trunk: a five-sided truncated pyramid at unit height. Returns vertices and indices to attach. */
function trunk(firstVertex: number, radius: number): { verts: number[]; idx: number[] } {
  const verts: number[] = [];
  const idx: number[] = [];
  for (let s = 0; s < TRUNK_SIDES; s++) {
    const a = (s / TRUNK_SIDES) * Math.PI * 2;
    for (let level = 0; level < 2; level++) {
      const rr = radius * (level === 0 ? TRUNK_FLARE : 1);
      verts.push(Math.cos(a) * rr, level, Math.sin(a) * rr, Math.cos(a), 0, Math.sin(a), 0.6, 1, 0, 0);
    }
    const b0 = firstVertex + s * 2;
    const t0 = b0 + 1;
    const b1 = firstVertex + ((s + 1) % TRUNK_SIDES) * 2;
    const t1 = b1 + 1;
    idx.push(b0, t0, b1, b1, t0, t1);
  }
  return { verts, idx };
}

/** Broadleaf canopy or shrub. The same seed always gives the same shape. */
function buildLumpShape(style: LumpStyle, seed: number, subdivisions: number): Shape {
  const sphere = icosphere(subdivisions);
  const lumps: { cx: number; cy: number; cz: number; r: number }[] = [{ cx: 0, cy: 0, cz: 0, r: style.core }];
  for (let k = 0; k < style.lumps; k++) {
    const u = unit(hashInts(seed, k, 1)) * 2 - 1;
    const a = unit(hashInts(seed, k, 2)) * Math.PI * 2;
    // Bumps more at the top and around the perimeter than at the bottom.
    const y = Math.min(1, Math.max(-1, u * 0.75 + style.yBias));
    const h = Math.sqrt(Math.max(0, 1 - y * y));
    const off = style.offMin + (style.offMax - style.offMin) * unit(hashInts(seed, k, 3));
    const r = style.rMin + (style.rMax - style.rMin) * unit(hashInts(seed, k, 4));
    lumps.push({ cx: Math.cos(a) * h * off, cy: y * off, cz: Math.sin(a) * h * off, r });
  }
  const n = sphere.pos.length / 3;
  const radius = new Float32Array(n);
  const winner = new Int32Array(n);
  let rMax = 0;
  let rMin = Infinity;
  for (let i = 0; i < n; i++) {
    const dx = sphere.pos[i * 3]!;
    const dy = sphere.pos[i * 3 + 1]!;
    const dz = sphere.pos[i * 3 + 2]!;
    let best = 0;
    let bestK = 0;
    lumps.forEach((l, k) => {
      const b = dx * l.cx + dy * l.cy + dz * l.cz;
      const c = l.cx * l.cx + l.cy * l.cy + l.cz * l.cz - l.r * l.r;
      const t = b + Math.sqrt(Math.max(0, b * b - c));
      if (t > best) {
        best = t;
        bestK = k;
      }
    });
    radius[i] = best;
    winner[i] = bestK;
    rMax = Math.max(rMax, best);
    rMin = Math.min(rMin, best);
  }
  // First positions in sphere space (−1 to 1), then the height is converted to 0–1.
  const px = new Float32Array(n);
  const py = new Float32Array(n);
  const pz = new Float32Array(n);
  let yLo = Infinity;
  let yHi = -Infinity;
  for (let i = 0; i < n; i++) {
    const r = radius[i]! / rMax;
    let y = sphere.pos[i * 3 + 1]! * r;
    if (y < style.flatBottom) y = style.flatBottom + (y - style.flatBottom) * style.flatSquash;
    const narrow = 1 - style.taper * smooth01((y + 0.2) / 1.2);
    px[i] = sphere.pos[i * 3]! * r * narrow;
    pz[i] = sphere.pos[i * 3 + 2]! * r * narrow;
    py[i] = y;
    yLo = Math.min(yLo, y);
    yHi = Math.max(yHi, y);
  }
  const ySpan = yHi - yLo;
  const verts: number[] = [];
  for (let i = 0; i < n; i++) {
    const dx = sphere.pos[i * 3]!;
    const dy = sphere.pos[i * 3 + 1]!;
    const dz = sphere.pos[i * 3 + 2]!;
    const l = lumps[winner[i]!]!;
    // Normal: a mix of the direction from the canopy centre and from the centre of the winning bump.
    let nx = dx * 0.35 + (dx * radius[i]! - l.cx) * 0.65;
    let ny = dy * 0.35 + (dy * radius[i]! - l.cy) * 0.65;
    let nz = dz * 0.35 + (dz * radius[i]! - l.cz) * 0.65;
    const nl = Math.hypot(nx, ny, nz) || 1;
    nx /= nl;
    ny /= nl;
    nz /= nl;
    // Shading: notches between bumps and the underside of the canopy are darker.
    const crease = (radius[i]! - rMin) / (rMax - rMin || 1);
    const up = dy * 0.5 + 0.5;
    const shade = (0.35 + 0.65 * Math.min(1, crease * 1.4)) * (0.45 + 0.55 * Math.min(1, up * 1.3));
    const flutter = 0.35 + 0.65 * Math.min(1, Math.hypot(px[i]!, pz[i]!));
    const phase = unit(hashInts(seed, winner[i]!, 9));
    // The vertical component of the normal is divided by the axis scale: height 0–1 corresponds to the ySpan range in sphere space.
    verts.push(px[i]!, (py[i]! - yLo) / ySpan, pz[i]!, nx, ny * ySpan, nz, shade, 0, flutter, phase);
  }
  const idx = sphere.idx.slice();
  if (style.trunk > 0) {
    const t = trunk(n, style.trunk);
    verts.push(...t.verts);
    idx.push(...t.idx);
  }
  return { vertices: Float32Array.from(verts), indices: Uint16Array.from(idx) };
}

/** Conifer: an outline of tiers revolved around the axis. Each tier is a cone whose lower edge overhangs the tier below. */
function buildConiferShape(seed: number, sides: number): Shape {
  const C = CONIFER;
  const envelope = (y: number): number => Math.pow(Math.max(0, 1 - y), C.envelopePower);
  // Outline in the (radius, height) plane from the bottom centre to the tip, counter-clockwise around the mass.
  const profile: { r: number; y: number; tip: boolean }[] = [{ r: 0, y: 0, tip: false }];
  for (let k = 0; k < C.tiers; k++) {
    const yb = (k / C.tiers) * C.tiersTop;
    profile.push({ r: envelope(yb), y: yb, tip: true });
    if (k < C.tiers - 1) {
      const yt = ((k + 1) / C.tiers) * C.tiersTop + C.overlap;
      profile.push({ r: envelope(yt) * C.innerRadius, y: yt, tip: false });
    }
  }
  profile.push({ r: 0, y: 1, tip: false });

  const verts: number[] = [];
  const idx: number[] = [];
  const ringRadius = (p: number, s: number): number => {
    const pt = profile[p]!;
    // The tier edges are not a circle: each lobe has a different length.
    return pt.tip ? pt.r * (1 - C.wobble * unit(hashInts(seed, p, s % sides))) : pt.r;
  };
  for (let p = 0; p + 1 < profile.length; p++) {
    const a = profile[p]!;
    const b = profile[p + 1]!;
    // Outward normal of an outline segment: the segment direction rotated by a quarter turn to the right.
    const nr = b.y - a.y;
    const ny = -(b.r - a.r);
    const nl = Math.hypot(nr, ny) || 1;
    const first = verts.length / VERTEX_FLOATS;
    for (let s = 0; s <= sides; s++) {
      const ang = (s / sides) * Math.PI * 2;
      const cos = Math.cos(ang);
      const sin = Math.sin(ang);
      for (const [pi, pt] of [
        [p, a],
        [p + 1, b],
      ] as const) {
        const r = ringRadius(pi, s);
        const shade = pt.tip ? 1 : pt.r === 0 && pt.y === 1 ? 0.95 : 0.3;
        const flutter = pt.tip ? 1 : 0.25;
        verts.push(cos * r, pt.y, sin * r, (cos * nr) / nl, ny / nl, (sin * nr) / nl, shade, 0, flutter, unit(hashInts(seed, 77, s % sides)));
      }
    }
    for (let s = 0; s < sides; s++) {
      const a0 = first + s * 2;
      const b0 = a0 + 1;
      const a1 = a0 + 2;
      const b1 = a0 + 3;
      // Counter-clockwise when viewed from outside.
      idx.push(a0, b0, a1, a1, b0, b1);
    }
  }
  const t = trunk(verts.length / VERTEX_FLOATS, C.trunk);
  verts.push(...t.verts);
  idx.push(...t.idx);
  return { vertices: Float32Array.from(verts), indices: Uint16Array.from(idx) };
}

/** Levels of detail: sphere subdivision count for broadleaf and side count for conifer, from the coarsest. */
const LOD_SUBDIVISIONS = [1, 2];
const LOD_CONIFER_SIDES = [6, 10];

function buildShape(species: TreeSpecies, seed: number, lod: number): Shape {
  if (species === 'conifer') return buildConiferShape(seed, LOD_CONIFER_SIDES[Math.min(lod, LOD_CONIFER_SIDES.length - 1)]!);
  return buildLumpShape(LUMP_STYLE[species], seed, LOD_SUBDIVISIONS[Math.min(lod, LOD_SUBDIVISIONS.length - 1)]!);
}

/** Vertex layout of a shape: position, normal, shading (attribute locations in `TREE_ATTRIBS`). */
export const TREE_VERTEX_LAYOUT: VertexLayout = {
  stride: VERTEX_FLOATS * 4,
  attribs: [
    { name: 'a_pos', size: 3, type: 'f32', offset: 0 },
    { name: 'a_normal', size: 3, type: 'f32', offset: 12 },
    { name: 'a_shade', size: 4, type: 'f32', offset: 24 },
  ],
};

/** Per-instance layout, `TREE_INSTANCE_FLOATS` floats (see `packTreeInstances`). */
export const TREE_INSTANCE_LAYOUT: VertexLayout = {
  stride: TREE_INSTANCE_FLOATS * 4,
  attribs: [
    { name: 'i_base', size: 4, type: 'f32', offset: 0 },
    { name: 'i_shape', size: 4, type: 'f32', offset: 16 },
    { name: 'i_extra', size: 4, type: 'f32', offset: 32 },
  ],
};

/** Where culling finds the base point, canopy radius and height inside one instance (float offsets). */
export const TREE_INSTANCE_BOUNDS = { position: 0, radius: 3, height: 4 } as const;

/** One group of trees of the same shape: the shape in several levels of detail and the instances that share it. */
export interface TreeBatch {
  species: TreeSpecies;
  /** Meshes from the coarsest to the finest. */
  lods: MeshData[];
  /** All instances of the group, in the order of `TREE_INSTANCE_LAYOUT`. */
  instances: Float32Array;
  /** Palette rows: dark canopy, middle, foliage, trunk, second foliage hue. */
  rows: [number, number, number, number, number];
  /** Evergreen group (by material). */
  evergreen: boolean;
}

/** Number of levels of detail the generator supports. */
export const TREE_LOD_COUNT = LOD_SUBDIVISIONS.length;

/** Builds a group: shape given by species and seed, all levels of detail, instances in the order of TREE_INSTANCE_FLOATS. */
export function buildTreeBatch(species: TreeSpecies, seed: number, instances: Float32Array, material: TreeMaterial): TreeBatch {
  const lods: MeshData[] = [];
  for (let lod = 0; lod < TREE_LOD_COUNT; lod++) {
    const shape = buildShape(species, seed, lod);
    lods.push({ layout: TREE_VERTEX_LAYOUT, vertices: shape.vertices, indices: shape.indices, count: shape.indices.length });
  }
  return {
    species,
    lods,
    instances,
    rows: [material.deep, material.mid, material.leaf, material.trunk, material.leafAlt],
    evergreen: material.evergreen ?? false,
  };
}

/** How far into the canopy the trunk reaches: a part in a leafy canopy, almost to the top for a bare tree. */
const TRUNK_REACH_LEAFY = 0.25;
const TRUNK_REACH_BARE = 0.72;

/** Uniforms of one batch for the vegetation material at the given broadleaf foliage density (0–1). */
export function treeBatchUniforms(batch: TreeBatch, foliage: number): Uniforms {
  const r = batch.rows;
  return {
    u_rows: { ivec4: [r[0], r[1], r[2], r[3]] },
    u_rowAlt: { int: r[4] },
    u_evergreen: { int: batch.evergreen ? 1 : 0 },
    u_trunkReach: { float: batch.evergreen ? TRUNK_REACH_LEAFY : lerp(TRUNK_REACH_BARE, TRUNK_REACH_LEAFY, foliage) },
  };
}

/** Writes trees into the instance array. */
export function packTreeInstances(trees: readonly PlantedTree[]): Float32Array {
  const out = new Float32Array(trees.length * TREE_INSTANCE_FLOATS);
  trees.forEach((t, i) => {
    const o = i * TREE_INSTANCE_FLOATS;
    out[o] = t.x;
    out[o + 1] = t.y;
    out[o + 2] = t.z;
    out[o + 3] = t.radius;
    out[o + 4] = t.height;
    out[o + 5] = Math.cos(t.yaw);
    out[o + 6] = Math.sin(t.yaw);
    out[o + 7] = t.tint;
    out[o + 8] = t.crownBase;
    out[o + 9] = t.flex;
    out[o + 10] = t.phase;
    out[o + 11] = 0;
  });
  return out;
}

/** Splits trees into groups by species and shape variant and builds a mesh for each. Skips empty groups. */
export function buildTreeBatches(trees: readonly PlantedTree[], seed: number, materials: Readonly<Record<TreeSpecies, TreeMaterial>>): TreeBatch[] {
  const groups = new Map<string, { species: TreeSpecies; variant: number; trees: PlantedTree[] }>();
  for (const t of trees) {
    const variant = Math.min(VARIANTS[t.species] - 1, Math.floor(t.phase * VARIANTS[t.species]));
    const key = `${t.species}:${variant}`;
    let g = groups.get(key);
    if (!g) {
      g = { species: t.species, variant, trees: [] };
      groups.set(key, g);
    }
    g.trees.push(t);
  }
  const speciesOrder: TreeSpecies[] = ['round', 'tall', 'conifer', 'birch', 'shrub'];
  return [...groups.values()]
    .sort((a, b) => speciesOrder.indexOf(a.species) - speciesOrder.indexOf(b.species) || a.variant - b.variant)
    .map((g) => buildTreeBatch(g.species, hashInts(seed, speciesOrder.indexOf(g.species), g.variant), packTreeInstances(g.trees), materials[g.species]));
}
